/** Is (x, z) inside a plot (+ margin m)? Used to drop the city-fill houses that stand inside a plot. */
export function insideCityPlot(x: number, z: number, margin = 0): boolean {
  for (const p of CITY_PLOTS) {
    if (Math.abs(x - p.c[0]) > 260 || Math.abs(z - p.c[1]) > 260) continue;
    let neg = false, pos = false;
    for (let i = 0; i < 4; i++) {
      const a = p.poly[i]!, b = p.poly[(i + 1) % 4]!;
      const ex = b[0] - a[0], ez = b[1] - a[1], len = Math.hypot(ex, ez);
      const cr = (ex * (z - a[1]) - ez * (x - a[0])) / len; // signed distance to the edge line
      if (cr < -margin) neg = true; else if (cr > margin) pos = true;
    }
    if (!(neg && pos)) return true;
  }
  return false;
}
